import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Code Agent Execution Protocol","description":"","frontmatter":{"title":"Code Agent Execution Protocol"},"headers":[],"relativePath":"guide/agent-protocol.md","filePath":"guide/agent-protocol.md","lastUpdated":1793266312000}`),a={name:`guide/agent-protocol.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_15-execution-protocol-for-code-agents" tabindex="-1">15. Execution Protocol for Code Agents <a class="header-anchor" href="#_15-execution-protocol-for-code-agents" aria-label="Permalink to “15. Execution Protocol for Code Agents”">​</a></h1><h2 id="_15-1-generating-the-whole-project-from-documents-in-one-shot-is-not-allowed" tabindex="-1">15.1 Generating the whole project from documents in one shot is not allowed <a class="header-anchor" href="#_15-1-generating-the-whole-project-from-documents-in-one-shot-is-not-allowed" aria-label="Permalink to “15.1 Generating the whole project from documents in one shot is not allowed”">​</a></h2><p>Implementation must be phased.</p><p>For each phase, first inspect the current repository state, then create the task list and implementation plan.</p><p>If the repository already contains code:</p><ul><li>Do not overwrite existing working implementations.</li><li>Do not assume the previous architecture is obsolete.</li><li>Existing call paths and module dependencies must be analyzed.</li><li>Identify compatibility impact first, then decide the refactoring scope.</li><li>Keep existing tests and add regression tests.</li></ul><h2 id="_15-2-every-task-must-output" tabindex="-1">15.2 Every task must output <a class="header-anchor" href="#_15-2-every-task-must-output" aria-label="Permalink to “15.2 Every task must output”">​</a></h2><ol><li>The list of modified files.</li><li>The reason for the change.</li><li>Interface changes.</li><li>State machine impact.</li><li>Database migration impact.</li><li>Platform compatibility impact.</li><li>Security impact.</li><li>New tests.</li><li>The verification commands executed.</li><li>The acceptance results.</li><li>Unresolved issues.</li></ol><p>Submitting code without stating the verification results is not acceptable.</p><h2 id="_15-3-the-agent-s-working-order" tabindex="-1">15.3 The agent&#39;s working order <a class="header-anchor" href="#_15-3-the-agent-s-working-order" aria-label="Permalink to “15.3 The agent&#39;s working order”">​</a></h2><p>Every phase follows:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Inspect Repository</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Create Implementation Plan</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Define Interfaces</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Implement Minimal Vertical Slice</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Add Unit Tests</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Add Integration Tests</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Run Formatting and Linting</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Run Test Suite</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Review Security and Failure Paths</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Update Documentation</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Report Results</span></span></code></pre></div><p>Each phase must only move to the next one after its tests pass.</p><h2 id="_15-4-suggested-first-tasks" tabindex="-1">15.4 Suggested first tasks <a class="header-anchor" href="#_15-4-suggested-first-tasks" aria-label="Permalink to “15.4 Suggested first tasks”">​</a></h2><h3 id="task-001-domain-model" tabindex="-1">Task 001: Domain model <a class="header-anchor" href="#task-001-domain-model" aria-label="Permalink to “Task 001: Domain model”">​</a></h3><p>Implement Resource, Dependency, HealthStatus, Evidence, Diagnosis, RecoveryPolicy, RecoveryRun, RecoveryAction, VerificationResult and AuditEvent.</p><p>Deliverables:</p><ul><li>Type definitions.</li><li>State transition rules.</li><li>Serialization and deserialization tests.</li><li>Invalid state transition tests.</li><li>Domain model documentation.</li></ul><h3 id="task-002-configuration-and-dependency-graph" tabindex="-1">Task 002: Configuration and dependency graph <a class="header-anchor" href="#task-002-configuration-and-dependency-graph" aria-label="Permalink to “Task 002: Configuration and dependency graph”">​</a></h3><p>Implement configuration parsing, reference validation, dependency graph construction, cycle detection and dependency condition validation.</p><p>Deliverables:</p><ul><li>A configuration schema or equivalent validation rules.</li><li>The dependency graph algorithm.</li><li>Error path location.</li><li>Tests for valid configurations, missing dependencies, duplicate IDs and dependency cycles.</li></ul><h3 id="task-003-recovery-state-machine" tabindex="-1">Task 003: Recovery state machine <a class="header-anchor" href="#task-003-recovery-state-machine" aria-label="Permalink to “Task 003: Recovery state machine”">​</a></h3><p>Implement RecoveryRun state transitions, recovery budgets, per-resource mutexes, action execution and the verification loop.</p><p>Deliverables:</p><ul><li>The complete state machine.</li><li>Re-diagnosis after failure.</li><li>A second candidate plan.</li><li>Unknown action outcome handling.</li><li>Concurrent recovery tests.</li></ul><h3 id="task-004-sqlite-persistence" tabindex="-1">Task 004: SQLite persistence <a class="header-anchor" href="#task-004-sqlite-persistence" aria-label="Permalink to “Task 004: SQLite persistence”">​</a></h3><p>Implement database migrations, RecoveryRun persistence, action records and recovery task resumption.</p><p>Deliverables:</p><ul><li>The database schema.</li><li>Transaction boundary documentation.</li><li>Process crash tests.</li><li>Database migration tests.</li><li>Unfinished task recovery tests.</li></ul><h3 id="task-005-plugin-host" tabindex="-1">Task 005: Plugin Host <a class="header-anchor" href="#task-005-plugin-host" aria-label="Permalink to “Task 005: Plugin Host”">​</a></h3><p>Implement JSON-RPC stdio, the plugin lifecycle, message size limits, timeouts and cancellation.</p><p>Deliverables:</p><ul><li>Plugin protocol documentation.</li><li>A sample plugin.</li><li>Protocol tests.</li><li>Heavy-output tests.</li><li>Plugin crash and timeout tests.</li></ul><h3 id="task-006-notification-engine" tabindex="-1">Task 006: Notification Engine <a class="header-anchor" href="#task-006-notification-engine" aria-label="Permalink to “Task 006: Notification Engine”">​</a></h3><p>Implement event rules, the persisted queue, Webhook, SMTP, local logs and delivery retries.</p><p>Deliverables:</p><ul><li>A unified notification interface.</li><li>The event model.</li><li>The persisted queue.</li><li>Channel implementations.</li><li>Network-outage retry tests.</li><li>Credential redaction tests.</li></ul><h3 id="task-007-cli" tabindex="-1">Task 007: CLI <a class="header-anchor" href="#task-007-cli" aria-label="Permalink to “Task 007: CLI”">​</a></h3><p>Implement commands for status, resources, the dependency graph, fault history, recovery history and notification status.</p><p>Deliverables:</p><ul><li>CLI commands.</li><li>Error output conventions.</li><li>Help documentation.</li><li>Integration tests.</li></ul><h3 id="task-008-first-real-recovery-scenario" tabindex="-1">Task 008: First real recovery scenario <a class="header-anchor" href="#task-008-first-real-recovery-scenario" aria-label="Permalink to “Task 008: First real recovery scenario”">​</a></h3><p>Prefer a simple scenario that can be verified automatically, for example automatic recovery after a controlled process exits.</p><p>Then implement the proxy and Cloudflare Tunnel scenario to verify the dependency recovery order.</p><p>Deliverables:</p><ul><li>Example configuration.</li><li>Fault injection tests.</li><li>A complete RecoveryRun record.</li><li>Notification results for both successful and failed recovery.</li></ul><hr>`,48)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};